mapper.update:
UPDATE goal
SET
    goal_name = #{goalName},
    goal_amount = #{goalAmount},
    goal_date = #{goalDate}
WHERE goal_id = #{goalId}
AND user_id = #{userId}

UPDATE goal
SET is_collected = TRUE
WHERE goal_id = #{goalId}
AND user_id =#{userId}

UPDATE goal
SET goal_status = #{status}
WHERE goal_id = #{goalId}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM goal
    WHERE user_id = #{userId}
      AND goal_status = 'ACTIVE'
)
